<button class="ai-launch" onclick="toggleAI(true)"><span>✦</span> Tanya AI Setia</button>
<aside class="ai-panel" id="ai-panel" aria-label="Asisten AI Setia"><div class="ai-head"><div><strong>✦ AI Setia</strong><small>Asisten pencarian jasa digital</small></div><button onclick="toggleAI(false)" aria-label="Tutup">✕</button></div><div class="ai-messages" id="ai-messages"><div class="bubble">Hai! 👋 Ceritakan apa yang ingin kamu buat atau butuhkan. Aku bantu arahkan ke layanan yang cocok.</div></div><form class="ai-form" id="ai-form"><input id="ai-input" maxlength="1500" placeholder="Aku butuh bantuan membuat..." required><button type="submit">Kirim</button></form></aside>
<script>
function toggleAI(open){document.getElementById('ai-panel').classList.toggle('open',open);if(open)setTimeout(()=>document.getElementById('ai-input').focus(),100)}
const aiForm=document.getElementById('ai-form'),aiInput=document.getElementById('ai-input'),aiMessages=document.getElementById('ai-messages');
aiForm.addEventListener('submit',async e=>{e.preventDefault();const message=aiInput.value.trim();if(!message)return;const user=document.createElement('div');user.className='bubble user';user.textContent=message;aiMessages.appendChild(user);aiInput.value='';const pending=document.createElement('div');pending.className='bubble';pending.textContent='AI Setia sedang berpikir…';aiMessages.appendChild(pending);aiMessages.scrollTop=aiMessages.scrollHeight;try{const response=await fetch('{{ route('ai.chat') }}',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},body:JSON.stringify({message})});const data=await response.json();pending.textContent=data.reply||data.message||'Maaf, belum ada jawaban. Coba lagi.';}catch(err){pending.textContent='Belum bisa terhubung ke AI. Kamu tetap bisa mencari layanan lewat kolom pencarian.';}aiMessages.scrollTop=aiMessages.scrollHeight;});
</script>
